css:
.wc-accordion { border: 1px solid var(--wc-border-default); border-radius: var(--wc-radius-md); overflow: hidden; background-color: var(--wc-bg-surface); }
.wc-accordion-item { border-bottom: 1px solid var(--wc-border-subtle); }
.wc-accordion-item:last-child { border-bottom: none; }
.wc-accordion-header { width: 100%; display: flex; align-items: center; justify-content: space-between; padding: 1rem 1.25rem; font-size: 0.9375rem; font-weight: 600; color: var(--wc-text-primary); text-align: left; transition: background-color var(--wc-transition-fast); }
.wc-accordion-header:hover { background-color: var(--wc-bg-surface-hover); }
.wc-accordion-icon { width: 1rem; height: 1rem; transition: transform var(--wc-transition-smooth); color: var(--wc-text-secondary); }
.wc-accordion-item.is-expanded .wc-accordion-icon { transform: rotate(180deg); }
.wc-accordion-content { max-height: 0; overflow: hidden; transition: max-height var(--wc-transition-smooth), padding var(--wc-transition-smooth); color: var(--wc-text-secondary); font-size: 0.875rem; line-height: 1.6; }
.wc-accordion-item.is-expanded .wc-accordion-content { padding: 0 1.25rem 1.25rem; max-height: 200px; }

js:
export class Accordion {
  constructor(element) {
    this.element = typeof element === 'string' ? document.querySelector(element) : element;
    if (!this.element) return;
    this.init();
  }
  init() {
    this.element.querySelectorAll('.wc-accordion-header').forEach(header => {
      header.addEventListener('click', () => {
        const item = header.closest('.wc-accordion-item');
        const isExpanded = item.classList.contains('is-expanded');
        if (!this.element.hasAttribute('data-wc-multiple')) {
          this.element.querySelectorAll('.wc-accordion-item').forEach(i => i.classList.remove('is-expanded'));
        }
        item.classList.toggle('is-expanded', !isExpanded);
      });
    });
  }
}
export function initAccordions() {
  document.querySelectorAll('.wc-accordion').forEach(el => new Accordion(el));
}

css:
.wc-tabs { display: flex; flex-direction: column; width: 100%; max-width: 500px; }
.wc-tabs-list { display: flex; border-bottom: 1px solid var(--wc-border-subtle); gap: 0.5rem; }
.wc-tab { padding: 0.625rem 1rem; font-size: 0.875rem; font-weight: 500; color: var(--wc-text-secondary); border-bottom: 2px solid transparent; transition: all var(--wc-transition-fast); margin-bottom: -1px; }
.wc-tab:hover { color: var(--wc-text-primary); }
.wc-tab.is-active { color: var(--wc-color-primary-400); border-bottom-color: var(--wc-color-primary-500); font-weight: 600; }
.wc-tab-panel { padding: 1.25rem 0; display: none; font-size: 0.875rem; color: var(--wc-text-secondary); line-height: 1.6; }
.wc-tab-panel.is-active { display: block; }

js:
export class Tabs {
  constructor(element) {
    this.element = typeof element === 'string' ? document.querySelector(element) : element;
    if (!this.element) return;
    this.tabs = this.element.querySelectorAll('.wc-tab');
    this.panels = this.element.querySelectorAll('.wc-tab-panel');
    this.init();
  }
  init() {
    this.tabs.forEach((tab, idx) => {
      tab.addEventListener('click', () => this.activate(idx));
    });
  }
  activate(index) {
    this.tabs.forEach((t, i) => t.classList.toggle('is-active', i === index));
    this.panels.forEach((p, i) => p.classList.toggle('is-active', i === index));
  }
}
export function initTabsComponent() {
  document.querySelectorAll('.wc-tabs').forEach(el => new Tabs(el));
}

css:
.wc-badge { display: inline-flex; align-items: center; gap: 0.375rem; font-size: 0.75rem; font-weight: 500; padding: 0.1875rem 0.625rem; border-radius: var(--wc-radius-full); background-color: var(--wc-bg-surface-raised); color: var(--wc-text-secondary); border: 1px solid var(--wc-border-default); line-height: 1; }
.wc-badge-primary { background-color: rgba(99, 102, 241, 0.15); color: var(--wc-color-primary-400); border-color: rgba(99, 102, 241, 0.3); }
.wc-badge-success { background-color: rgba(34, 197, 94, 0.15); color: var(--wc-color-success-500); border-color: rgba(34, 197, 94, 0.3); }
.wc-badge-warning { background-color: rgba(245, 158, 11, 0.15); color: var(--wc-color-warning-500); border-color: rgba(245, 158, 11, 0.3); }
.wc-badge-danger { background-color: rgba(239, 68, 68, 0.15); color: var(--wc-color-danger-500); border-color: rgba(239, 68, 68, 0.3); }
.wc-badge-dot { width: 6px; height: 6px; border-radius: 50%; background-color: currentColor; }

.wc-switch { display: inline-flex; align-items: center; gap: 0.75rem; cursor: pointer; user-select: none; font-size: 0.875rem; color: var(--wc-text-primary); }
.wc-switch-track { position: relative; width: 44px; height: 24px; background-color: var(--wc-bg-surface-raised); border: 1px solid var(--wc-border-default); border-radius: var(--wc-radius-full); transition: background-color var(--wc-transition-fast), border-color var(--wc-transition-fast); }
.wc-switch-thumb { position: absolute; top: 2px; left: 2px; width: 18px; height: 18px; background-color: var(--wc-text-secondary); border-radius: 50%; transition: transform var(--wc-transition-fast), background-color var(--wc-transition-fast); }
.wc-switch input { position: absolute; opacity: 0; width: 0; height: 0; }
.wc-switch input:checked + .wc-switch-track { background-color: var(--wc-color-primary-600); border-color: var(--wc-color-primary-500); }
.wc-switch input:checked + .wc-switch-track .wc-switch-thumb { transform: translateX(20px); background-color: #ffffff; }

.wc-segmented { display: inline-flex; background-color: var(--wc-bg-surface-raised); border: 1px solid var(--wc-border-default); border-radius: var(--wc-radius-md); padding: 3px; gap: 2px; }
.wc-segment-btn { padding: 0.375rem 0.875rem; font-size: 0.8125rem; font-weight: 500; color: var(--wc-text-secondary); border-radius: var(--wc-radius-sm); transition: all var(--wc-transition-fast); }
.wc-segment-btn:hover { color: var(--wc-text-primary); }
.wc-segment-btn.is-active { background-color: var(--wc-bg-surface); color: var(--wc-text-primary); box-shadow: var(--wc-shadow-sm); font-weight: 600; }

js:
export class SegmentedControl {
  constructor(element) {
    this.element = typeof element === 'string' ? document.querySelector(element) : element;
    if (!this.element) return;
    this.buttons = this.element.querySelectorAll('.wc-segment-btn');
    this.init();
  }
  init() {
    this.buttons.forEach(btn => {
      btn.addEventListener('click', () => {
        this.buttons.forEach(b => b.classList.remove('is-active'));
        btn.classList.add('is-active');
      });
    });
  }
}
export function initSegmentedControls() {
  document.querySelectorAll('.wc-segmented').forEach(el => new SegmentedControl(el));
}

css:
.wc-progress { width: 100%; max-width: 400px; height: 8px; background-color: var(--wc-bg-surface-raised); border-radius: var(--wc-radius-full); overflow: hidden; border: 1px solid var(--wc-border-subtle); position: relative; }
.wc-progress-bar { height: 100%; background: linear-gradient(90deg, var(--wc-color-primary-600), var(--wc-color-primary-400)); border-radius: var(--wc-radius-full); transition: width var(--wc-transition-base); }
.wc-progress-indeterminate .wc-progress-bar { width: 40%; position: absolute; animation: wc-progress-slide 1.5s infinite ease-in-out; }
@keyframes wc-progress-slide { 0% { left: -40%; } 100% { left: 100%; } }

.wc-stat-card { background-color: var(--wc-bg-surface); border: 1px solid var(--wc-border-default); border-radius: var(--wc-radius-lg); padding: 1.5rem; width: 100%; max-width: 300px; box-shadow: var(--wc-shadow-md); display: flex; flex-direction: column; gap: 0.75rem; }
.wc-stat-header { display: flex; align-items: center; justify-content: space-between; font-size: 0.8125rem; color: var(--wc-text-muted); font-weight: 500; }
.wc-stat-value { font-size: 1.875rem; font-weight: 700; color: var(--wc-text-primary); letter-spacing: -0.03em; }
.wc-stat-footer { display: flex; align-items: center; gap: 0.5rem; font-size: 0.75rem; color: var(--wc-text-secondary); }
.wc-trend-up { color: var(--wc-color-success-500); font-weight: 600; display: inline-flex; align-items: center; gap: 2px; }

.wc-skeleton { background: linear-gradient(90deg, var(--wc-bg-surface-raised) 25%, var(--wc-bg-surface-hover) 50%, var(--wc-bg-surface-raised) 75%); background-size: 200% 100%; animation: wc-shimmer 1.5s infinite; border-radius: var(--wc-radius-sm); }
.wc-skeleton-avatar { width: 44px; height: 44px; border-radius: 50%; }
.wc-skeleton-text { height: 12px; width: 100%; margin-bottom: 8px; }
.wc-skeleton-title { height: 18px; width: 60%; margin-bottom: 12px; }
@keyframes wc-shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }

.wc-tooltip-trigger { position: relative; display: inline-flex; }
.wc-tooltip { position: absolute; bottom: calc(100% + 8px); left: 50%; transform: translateX(-50%) translateY(4px); background-color: var(--wc-color-gray-950); color: #ffffff; font-size: 0.75rem; font-weight: 500; padding: 0.375rem 0.625rem; border-radius: var(--wc-radius-sm); white-space: nowrap; pointer-events: none; opacity: 0; visibility: hidden; transition: opacity var(--wc-transition-fast), transform var(--wc-transition-fast); border: 1px solid var(--wc-border-default); z-index: 100; }
.wc-tooltip-trigger:hover .wc-tooltip, .wc-tooltip-trigger:focus-visible .wc-tooltip { opacity: 1; visibility: visible; transform: translateX(-50%) translateY(0); }
